def cumulative_pnl(positions, prices):
    if not prices:
        return []
    total = 0.0
    out = [total]
    for t in range(1, len(prices)):
        # Yesterday's holding earns today's move
        total += positions[t - 1] * (prices[t] - prices[t - 1])
        out.append(total)
    return out
